tape( 'the function performs one of the matrix-vector operations `x = A*x`, or `x = A**T*x`, or `x = A**H*x` (row-major, lower, no-transpose, non-unit)', function test( t ) {
	var expected;
	var data;
	var out;
	var a;
	var x;

	data = rlntnu;

	a = new Complex64Array( data.A );
	x = new Complex64Array( data.x );

	expected = new Complex64Array( data.A_out );

	out = ctrmv( data.order, data.uplo, data.trans, data.diag, data.N, x, data.strideX, a, data.LDA );
	t.strictEqual( isSameComplex64Array( out, x ), true, 'returns expected value' );
	t.deepEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

